import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { 
  TrendingUp, 
  TrendingDown, 
  Target, 
  Clock, 
  Users, 
  Award,
  AlertTriangle,
  CheckCircle,
  DollarSign,
  BarChart3,
  Calendar,
  Zap
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  AreaChart,
  Area,
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  RadialBarChart,
  RadialBar,
  Legend
} from 'recharts';
import { getInitiatives, getAwardPoints, getDepartments } from '../lib/database';
import { formatCurrencyDisplay, formatCurrencyCompact, generateFinancialSummary } from '../lib/currency';

const COLORS = {
  primary: '#ea580c',
  secondary: '#4a4a4a',
  success: '#16a34a',
  warning: '#eab308',
  danger: '#dc2626',
  info: '#0ea5e9',
  purple: '#7c3aed',
  pink: '#ec4899'
};

function EnhancedDashboard({ statistics, onDataUpdate }) {
  const [initiatives, setInitiatives] = useState([]);
  const [awardPoints, setAwardPoints] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [timeRange, setTimeRange] = useState('3months');
  const [selectedMetric, setSelectedMetric] = useState('completion');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const [initiativesData, awardPointsData, departmentsData] = await Promise.all([
        getInitiatives(),
        getAwardPoints(),
        getDepartments()
      ]);
      setInitiatives(initiativesData);
      setAwardPoints(awardPointsData);
      setDepartments(departmentsData);
    } catch (error) {
      console.error('Error loading data:', error);
    }
  };

  // Enhanced KPI calculations
  const enhancedKPIs = {
    totalInitiatives: initiatives.length,
    completedInitiatives: initiatives.filter(i => i.status === 'مكتملة').length,
    inProgressInitiatives: initiatives.filter(i => i.status === 'قيد التنفيذ').length,
    delayedInitiatives: initiatives.filter(i => i.status === 'متأخرة').length,
    notStartedInitiatives: initiatives.filter(i => i.status === 'لم تبدأ').length,
    
    averageCompletion: initiatives.length > 0 
      ? Math.round(initiatives.reduce((sum, i) => sum + (i.completion_percentage || 0), 0) / initiatives.length)
      : 0,
    
    totalStrengthPoints: awardPoints.filter(p => p.point_type === 'نقطة قوة').length,
    totalImprovementPoints: awardPoints.filter(p => p.point_type === 'نقطة تحسين').length,
    
    completionRate: initiatives.length > 0 
      ? Math.round((initiatives.filter(i => i.status === 'مكتملة').length / initiatives.length) * 100)
      : 0,
    
    onTimeRate: initiatives.length > 0 
      ? Math.round(((initiatives.length - initiatives.filter(i => i.status === 'متأخرة').length) / initiatives.length) * 100)
      : 0
  };

  // Financial summary
  const financialSummary = generateFinancialSummary(initiatives);

  // Performance trends (mock data for demonstration)
  const performanceTrends = [
    { month: 'يناير', completion: 15, budget: 85, quality: 78 },
    { month: 'فبراير', completion: 28, budget: 82, quality: 81 },
    { month: 'مارس', completion: 42, budget: 79, quality: 85 },
    { month: 'أبريل', completion: 55, budget: 88, quality: 87 },
    { month: 'مايو', completion: 68, budget: 85, quality: 89 },
    { month: 'يونيو', completion: 75, budget: 91, quality: 92 },
    { month: 'يوليو', completion: 82, budget: 89, quality: 94 },
    { month: 'أغسطس', completion: 88, budget: 93, quality: 96 },
    { month: 'سبتمبر', completion: enhancedKPIs.averageCompletion, budget: 95, quality: 98 }
  ];

  // Department performance radar data
  const departmentRadarData = departments.map(dept => {
    const deptInitiatives = initiatives.filter(i => i.department === dept.name);
    const deptAwardPoints = awardPoints.filter(p => p.department === dept.name);
    
    return {
      department: dept.name.replace('إدارة ', ''),
      completion: deptInitiatives.length > 0 
        ? Math.round(deptInitiatives.reduce((sum, i) => sum + (i.completion_percentage || 0), 0) / deptInitiatives.length)
        : 0,
      quality: Math.min(100, 70 + Math.random() * 30), // Mock quality score
      efficiency: Math.min(100, 60 + Math.random() * 40), // Mock efficiency score
      innovation: deptAwardPoints.length * 10, // Innovation based on award points
      collaboration: Math.min(100, 50 + Math.random() * 50) // Mock collaboration score
    };
  });

  // Status distribution for pie chart
  const statusDistribution = [
    { name: 'مكتملة', value: enhancedKPIs.completedInitiatives, color: COLORS.success },
    { name: 'قيد التنفيذ', value: enhancedKPIs.inProgressInitiatives, color: COLORS.warning },
    { name: 'متأخرة', value: enhancedKPIs.delayedInitiatives, color: COLORS.danger },
    { name: 'لم تبدأ', value: enhancedKPIs.notStartedInitiatives, color: COLORS.secondary }
  ];

  // Progress indicators data
  const progressIndicators = [
    { 
      name: 'معدل الإنجاز', 
      value: enhancedKPIs.completionRate, 
      target: 85, 
      color: COLORS.primary,
      icon: Target
    },
    { 
      name: 'الالتزام بالمواعيد', 
      value: enhancedKPIs.onTimeRate, 
      target: 90, 
      color: COLORS.success,
      icon: Clock
    },
    { 
      name: 'جودة التنفيذ', 
      value: 92, 
      target: 95, 
      color: COLORS.info,
      icon: Award
    },
    { 
      name: 'رضا المستفيدين', 
      value: 88, 
      target: 90, 
      color: COLORS.purple,
      icon: Users
    }
  ];

  // Progress tracking data
  const progressData = [
    {
      title: 'نسبة الإكمال 0-25%',
      count: initiatives.filter(i => i.completion_percentage >= 0 && i.completion_percentage <= 25).length,
      total: initiatives.length,
      percentage: initiatives.length > 0 ? Math.round((initiatives.filter(i => i.completion_percentage >= 0 && i.completion_percentage <= 25).length / initiatives.length) * 100) : 0,
      color: 'bg-red-500'
    },
    {
      title: 'نسبة الإكمال 26-50%',
      count: initiatives.filter(i => i.completion_percentage >= 26 && i.completion_percentage <= 50).length,
      total: initiatives.length,
      percentage: initiatives.length > 0 ? Math.round((initiatives.filter(i => i.completion_percentage >= 26 && i.completion_percentage <= 50).length / initiatives.length) * 100) : 0,
      color: 'bg-yellow-500'
    },
    {
      title: 'نسبة الإكمال 51-75%',
      count: initiatives.filter(i => i.completion_percentage >= 51 && i.completion_percentage <= 75).length,
      total: initiatives.length,
      percentage: initiatives.length > 0 ? Math.round((initiatives.filter(i => i.completion_percentage >= 51 && i.completion_percentage <= 75).length / initiatives.length) * 100) : 0,
      color: 'bg-blue-500'
    },
    {
      title: 'نسبة الإكمال 76-100%',
      count: initiatives.filter(i => i.completion_percentage >= 76 && i.completion_percentage <= 100).length,
      total: initiatives.length,
      percentage: initiatives.length > 0 ? Math.round((initiatives.filter(i => i.completion_percentage >= 76 && i.completion_percentage <= 100).length / initiatives.length) * 100) : 0,
      color: 'bg-green-500'
    }
  ];

  const budgetEfficiency = initiatives.length > 0 ? 
    Math.round((initiatives.reduce((sum, i) => sum + (i.planned_budget - i.used_budget), 0) / initiatives.reduce((sum, i) => sum + i.planned_budget, 0)) * 100) : 0;

  const scheduleCompliance = initiatives.length > 0 ? 
    Math.round((initiatives.filter(i => i.status === 'مكتملة' || i.status === 'قيد التنفيذ').length / initiatives.length) * 100) : 0;

  return (
    <div className="space-y-6">
      {/* Progress Tracking Section */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2" style={{color: 'var(--brand-orange)'}}>
            <TrendingUp className="h-5 w-5" />
            تتبع التقدم والإنجازات
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {progressData.map((item, index) => (
              <div key={index} className="bg-white rounded-lg border border-gray-200 p-4 hover:shadow-md transition-shadow">
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center gap-2">
                    <CheckCircle className="h-4 w-4 text-green-600" />
                    <span className="text-xs font-medium text-gray-600">إنجاز</span>
                  </div>
                </div>
                <h3 className="text-sm font-semibold text-gray-800 mb-2">{item.title}</h3>
                <div className="space-y-2">
                  <div className="flex items-center justify-between text-xs text-gray-600">
                    <span>التقدم</span>
                    <span>{item.count} / {item.total}</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2">
                    <div 
                      className={`h-2 rounded-full ${item.color}`}
                      style={{ width: `${item.percentage}%` }}
                    ></div>
                  </div>
                  <div className="text-xs text-gray-500">
                    {item.count} مبادرة في هذا النطاق
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-xs text-gray-600">نسبة الإنجاز</span>
                    <span className="text-sm font-bold text-gray-800">{item.percentage}%</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Key Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <DollarSign className="h-4 w-4" style={{color: 'var(--brand-orange)'}} />
                <span className="text-xs font-medium text-gray-600">ميزانية</span>
              </div>
            </div>
            <h3 className="text-sm font-semibold text-gray-800 mb-2">كفاءة الميزانية</h3>
            <div className="space-y-2">
              <div className="flex items-center justify-between text-xs text-gray-600">
                <span>التقدم</span>
                <span>{budgetEfficiency} / 100</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-2">
                <div 
                  className="h-2 rounded-full bg-blue-500"
                  style={{ width: `${budgetEfficiency}%` }}
                ></div>
              </div>
              <div className="text-xs text-gray-500">
                توفير {budgetEfficiency}% من الميزانية المخططة
              </div>
              <div className="flex items-center justify-between">
                <span className="text-xs text-gray-600">نسبة الإنجاز</span>
                <span className="text-sm font-bold text-gray-800">{budgetEfficiency}%</span>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <Calendar className="h-4 w-4 text-green-600" />
                <span className="text-xs font-medium text-gray-600">جدولة</span>
              </div>
            </div>
            <h3 className="text-sm font-semibold text-gray-800 mb-2">الالتزام بالجدولة</h3>
            <div className="space-y-2">
              <div className="flex items-center justify-between text-xs text-gray-600">
                <span>التقدم</span>
                <span>{scheduleCompliance} / 100</span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-2">
                <div 
                  className="h-2 rounded-full bg-green-500"
                  style={{ width: `${scheduleCompliance}%` }}
                ></div>
              </div>
              <div className="text-xs text-gray-500">
                {Math.round((scheduleCompliance / 100) * initiatives.length)} من {initiatives.length} مبادرة في الموعد المحدد
              </div>
              <div className="flex items-center justify-between">
                <span className="text-xs text-gray-600">نسبة الإنجاز</span>
                <span className="text-sm font-bold text-gray-800">{scheduleCompliance}%</span>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <AlertTriangle className="h-4 w-4 text-blue-600" />
                <span className="text-xs font-medium text-gray-600">إشعارات</span>
              </div>
            </div>
            <h3 className="text-sm font-semibold text-gray-800 mb-2">إجمالي الإشعارات</h3>
            <div className="space-y-2">
              <div className="text-2xl font-bold text-blue-600">{enhancedKPIs.delayedInitiatives + 1}</div>
              <div className="space-y-1">
                <div className="flex items-center justify-between text-xs">
                  <span className="text-red-600">تحذيرات عالية الأولوية</span>
                  <span className="font-semibold">{enhancedKPIs.delayedInitiatives}</span>
                </div>
                <div className="flex items-center justify-between text-xs">
                  <span className="text-green-600">إنجازات محققة</span>
                  <span className="font-semibold">{enhancedKPIs.completedInitiatives}</span>
                </div>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-xs text-gray-600">معدل التقدم</span>
                <span className="text-sm font-bold text-gray-800">{enhancedKPIs.averageCompletion}%</span>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Enhanced KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {/* Total Initiatives */}
        <Card className="relative overflow-hidden border-l-4 border-l-blue-500">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">إجمالي المبادرات</CardTitle>
            <BarChart3 className="h-4 w-4 text-blue-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-900">{enhancedKPIs.totalInitiatives}</div>
            <div className="flex items-center gap-2 mt-2">
              <Badge variant="outline" className="text-xs">
                {enhancedKPIs.completedInitiatives} مكتملة
              </Badge>
              <Badge variant="outline" className="text-xs text-yellow-600">
                {enhancedKPIs.inProgressInitiatives} قيد التنفيذ
              </Badge>
            </div>
            <div className="absolute top-0 right-0 w-16 h-16 bg-blue-500 opacity-10 rounded-full -mr-8 -mt-8"></div>
          </CardContent>
        </Card>

        {/* Average Completion */}
        <Card className="relative overflow-hidden border-l-4 border-l-green-500">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">متوسط نسبة الإكمال</CardTitle>
            <TrendingUp className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-900">{enhancedKPIs.averageCompletion}%</div>
            <Progress value={enhancedKPIs.averageCompletion} className="mt-2 h-2" />
            <p className="text-xs text-gray-500 mt-1">
              الهدف: 85%
            </p>
            <div className="absolute top-0 right-0 w-16 h-16 bg-green-500 opacity-10 rounded-full -mr-8 -mt-8"></div>
          </CardContent>
        </Card>

        {/* Budget Utilization */}
        <Card className="relative overflow-hidden border-l-4 border-l-orange-500">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">استخدام الميزانية</CardTitle>
            <DollarSign className="h-4 w-4 text-orange-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-900">
              {Math.round(statistics.budgetUtilization || 0)}%
            </div>
            <div className="text-sm text-gray-600 mt-1">
              {financialSummary.totalUsed} من {financialSummary.totalPlanned}
            </div>
            <div className="absolute top-0 right-0 w-16 h-16 bg-orange-500 opacity-10 rounded-full -mr-8 -mt-8"></div>
          </CardContent>
        </Card>

        {/* Award Points */}
        <Card className="relative overflow-hidden border-l-4 border-l-purple-500">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">نقاط الجائزة</CardTitle>
            <Award className="h-4 w-4 text-purple-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-900">
              {enhancedKPIs.totalStrengthPoints + enhancedKPIs.totalImprovementPoints}
            </div>
            <div className="flex items-center gap-2 mt-2">
              <Badge className="bg-green-100 text-green-800 text-xs">
                {enhancedKPIs.totalStrengthPoints} قوة
              </Badge>
              <Badge className="bg-yellow-100 text-yellow-800 text-xs">
                {enhancedKPIs.totalImprovementPoints} تحسين
              </Badge>
            </div>
            <div className="absolute top-0 right-0 w-16 h-16 bg-purple-500 opacity-10 rounded-full -mr-8 -mt-8"></div>
          </CardContent>
        </Card>
      </div>

      {/* Performance Indicators */}
      <Card>
        <CardHeader>
          <CardTitle className="text-orange-600 flex items-center gap-2">
            <Zap className="h-5 w-5" />
            مؤشرات الأداء الرئيسية
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {progressIndicators.map((indicator, index) => {
              const IconComponent = indicator.icon;
              const isOnTarget = indicator.value >= indicator.target;
              
              return (
                <div key={index} className="text-center">
                  <div className="flex items-center justify-center mb-3">
                    <div 
                      className="w-16 h-16 rounded-full flex items-center justify-center"
                      style={{ backgroundColor: `${indicator.color}20` }}
                    >
                      <IconComponent 
                        className="h-8 w-8" 
                        style={{ color: indicator.color }}
                      />
                    </div>
                  </div>
                  <h3 className="font-medium text-gray-900 mb-2">{indicator.name}</h3>
                  <div className="text-2xl font-bold mb-2" style={{ color: indicator.color }}>
                    {indicator.value}%
                  </div>
                  <Progress 
                    value={indicator.value} 
                    className="h-2 mb-2"
                    style={{ 
                      '--progress-background': indicator.color 
                    }}
                  />
                  <div className="flex items-center justify-center gap-1 text-xs">
                    {isOnTarget ? (
                      <CheckCircle className="h-3 w-3 text-green-500" />
                    ) : (
                      <AlertTriangle className="h-3 w-3 text-yellow-500" />
                    )}
                    <span className="text-gray-500">
                      الهدف: {indicator.target}%
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Performance Trends */}
        <Card>
          <CardHeader>
            <CardTitle className="text-orange-600">اتجاهات الأداء</CardTitle>
            <div className="flex gap-2">
              {['completion', 'budget', 'quality'].map(metric => (
                <Button
                  key={metric}
                  variant={selectedMetric === metric ? "default" : "outline"}
                  size="sm"
                  className={`text-xs ${
                    selectedMetric === metric 
                      ? 'bg-orange-600 hover:bg-orange-700' 
                      : 'border-gray-300'
                  }`}
                  onClick={() => setSelectedMetric(metric)}
                >
                  {metric === 'completion' ? 'الإنجاز' : 
                   metric === 'budget' ? 'الميزانية' : 'الجودة'}
                </Button>
              ))}
            </div>
          </CardHeader>
          <CardContent>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={performanceTrends}>
                  <defs>
                    <linearGradient id="colorGradient" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor={COLORS.primary} stopOpacity={0.3}/>
                      <stop offset="95%" stopColor={COLORS.primary} stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="month" fontSize={12} />
                  <YAxis domain={[0, 100]} />
                  <Tooltip 
                    formatter={(value) => [`${value}%`, 
                      selectedMetric === 'completion' ? 'نسبة الإنجاز' : 
                      selectedMetric === 'budget' ? 'كفاءة الميزانية' : 'مؤشر الجودة'
                    ]}
                    labelStyle={{ direction: 'rtl' }}
                  />
                  <Area 
                    type="monotone" 
                    dataKey={selectedMetric} 
                    stroke={COLORS.primary}
                    strokeWidth={3}
                    fillOpacity={1}
                    fill="url(#colorGradient)"
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>

        {/* Status Distribution */}
        <Card>
          <CardHeader>
            <CardTitle className="text-orange-600">توزيع حالات المبادرات</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-80">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={statusDistribution}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={120}
                    paddingAngle={5}
                    dataKey="value"
                  >
                    {statusDistribution.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.color} />
                    ))}
                  </Pie>
                  <Tooltip 
                    formatter={(value, name) => [value, name]}
                    labelStyle={{ direction: 'rtl' }}
                  />
                  <Legend 
                    verticalAlign="bottom" 
                    height={36}
                    formatter={(value) => value}
                  />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Department Performance Matrix */}
      <Card>
        <CardHeader>
          <CardTitle className="text-orange-600">مصفوفة أداء الإدارات</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead>
                <tr className="border-b border-gray-200">
                  <th className="text-right p-3 font-medium text-gray-700">الإدارة</th>
                  <th className="text-center p-3 font-medium text-gray-700">نسبة الإكمال</th>
                  <th className="text-center p-3 font-medium text-gray-700">الجودة</th>
                  <th className="text-center p-3 font-medium text-gray-700">الكفاءة</th>
                  <th className="text-center p-3 font-medium text-gray-700">الابتكار</th>
                  <th className="text-center p-3 font-medium text-gray-700">التقييم العام</th>
                </tr>
              </thead>
              <tbody>
                {departmentRadarData.map((dept, index) => {
                  const overallScore = Math.round((dept.completion + dept.quality + dept.efficiency + Math.min(100, dept.innovation) + dept.collaboration) / 5);
                  
                  return (
                    <tr key={index} className="border-b border-gray-100 hover:bg-gray-50">
                      <td className="p-3 font-medium">{dept.department}</td>
                      <td className="p-3 text-center">
                        <div className="flex items-center justify-center gap-2">
                          <Progress value={dept.completion} className="w-16 h-2" />
                          <span className="text-sm font-medium">{dept.completion}%</span>
                        </div>
                      </td>
                      <td className="p-3 text-center">
                        <div className="flex items-center justify-center gap-2">
                          <Progress value={dept.quality} className="w-16 h-2" />
                          <span className="text-sm font-medium">{Math.round(dept.quality)}%</span>
                        </div>
                      </td>
                      <td className="p-3 text-center">
                        <div className="flex items-center justify-center gap-2">
                          <Progress value={dept.efficiency} className="w-16 h-2" />
                          <span className="text-sm font-medium">{Math.round(dept.efficiency)}%</span>
                        </div>
                      </td>
                      <td className="p-3 text-center">
                        <Badge 
                          className={`${
                            dept.innovation >= 50 ? 'bg-green-100 text-green-800' :
                            dept.innovation >= 30 ? 'bg-yellow-100 text-yellow-800' :
                            'bg-red-100 text-red-800'
                          }`}
                        >
                          {Math.min(100, dept.innovation)}%
                        </Badge>
                      </td>
                      <td className="p-3 text-center">
                        <Badge 
                          className={`${
                            overallScore >= 80 ? 'bg-green-100 text-green-800' :
                            overallScore >= 60 ? 'bg-yellow-100 text-yellow-800' :
                            'bg-red-100 text-red-800'
                          }`}
                        >
                          {overallScore >= 80 ? 'ممتاز' :
                           overallScore >= 60 ? 'جيد' : 'يحتاج تحسين'}
                        </Badge>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Quick Actions */}
      <Card>
        <CardHeader>
          <CardTitle className="text-orange-600">إجراءات سريعة</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="p-4 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer transition-colors">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center">
                  <Calendar className="h-5 w-5 text-blue-600" />
                </div>
                <div>
                  <h3 className="font-medium text-gray-900">جدولة اجتماع مراجعة</h3>
                  <p className="text-sm text-gray-500">تحديد موعد لمراجعة التقدم</p>
                </div>
              </div>
            </div>

            <div className="p-4 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer transition-colors">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">
                  <CheckCircle className="h-5 w-5 text-green-600" />
                </div>
                <div>
                  <h3 className="font-medium text-gray-900">إنشاء تقرير شهري</h3>
                  <p className="text-sm text-gray-500">تقرير شامل عن الإنجازات</p>
                </div>
              </div>
            </div>

            <div className="p-4 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer transition-colors">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-orange-100 rounded-lg flex items-center justify-center">
                  <AlertTriangle className="h-5 w-5 text-orange-600" />
                </div>
                <div>
                  <h3 className="font-medium text-gray-900">متابعة المتأخرات</h3>
                  <p className="text-sm text-gray-500">مراجعة المبادرات المتأخرة</p>
                </div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

export default EnhancedDashboard;
